const express = require('express');
const router = express.Router();
const pool = require('../db');
const { requireAuth, requireRole, validateCsrfToken} = require('../middleware/auth');
const multer = require('multer');
const path = require('path');

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, path.join(__dirname, '..', 'public', 'uploads')),
  filename: (req, file, cb) => cb(null, Date.now() + '-' + file.originalname)
});
const upload = multer({ storage, limits: { fileSize: 5 * 1024 * 1024 } });

// GET /admin - Dashboard
router.get('/', requireAuth, requireRole('admin'), async (req, res) => {
  try {
    const [eventsCount, photosCount, videosCount, messagesCount, recentMessages, settings] = await Promise.all([
      pool.query('SELECT COUNT(*) FROM events'),
      pool.query('SELECT COUNT(*) FROM photos'),
      pool.query('SELECT COUNT(*) FROM videos'),
      pool.query('SELECT COUNT(*) FROM contact_messages'),
      pool.query('SELECT * FROM contact_messages ORDER BY created_at DESC LIMIT 5'),
      pool.query('SELECT key, value FROM site_settings ORDER BY key ASC')
    ]);

    res.render('admin-dashboard', {
      title: 'Admin Dashboard | Medicine Waves',
      stats: {
        events: parseInt(eventsCount.rows[0].count),
        photos: parseInt(photosCount.rows[0].count),
        videos: parseInt(videosCount.rows[0].count),
        messages: parseInt(messagesCount.rows[0].count)
      },
      recentMessages: recentMessages.rows,
      settings: settings.rows
    });
  } catch (err) {
    console.error('Error in GET /admin:', err);
    res.status(500).render('500', { title: 'Error' });
  }
});

// POST /admin/settings - Update site settings
router.post('/settings', requireAuth, requireRole('admin'), upload.single('file_upload'), validateCsrfToken, async (req, res) => {
  try {
    const { setting_key, setting_value } = req.body;

    let finalValue = (setting_value || '').trim();
    if (req.file) {
      finalValue = '/uploads/' + req.file.filename;
    }

    await pool.query(
      'UPDATE site_settings SET value = $1, updated_at = NOW() WHERE key = $2',
      [finalValue, setting_key]
    );

    res.redirect('/admin?success=' + encodeURIComponent('Setting updated successfully'));
  } catch (err) {
    console.error('Error in POST /admin/settings:', err);
    res.redirect('/admin?error=' + encodeURIComponent('Failed to update setting'));
  }
});

module.exports = router;

