const express = require('express');
const router = express.Router();
const bcrypt = require('bcrypt');
const crypto = require('crypto');
const pool = require('../db');
const rateLimit = require('express-rate-limit');
const { requireAuth, validateCsrfToken} = require('../middleware/auth');

const loginLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 10, message: 'Too many login attempts, please try again later.' });
const magicLinkLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 3, message: 'Too many requests. Please try again later.' });
const setPasswordLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 5, message: 'Too many attempts. Please try again later.' });

// GET /login
router.get('/login', (req, res) => {
  if (req.session.userId) return res.redirect('/dashboard');
  res.render('login', { title: 'Login | Medicine Waves', error: null });
});

// POST /login
router.post('/login', loginLimiter, validateCsrfToken, async (req, res) => {
  try {
    const email = (req.body.email || '').trim().toLowerCase();
    const password = req.body.password || '';

    if (!email || !password) {
      return res.render('login', { title: 'Login | Medicine Waves', error: 'Please enter email and password.' });
    }

    // TEST_MODE backdoor
    if (process.env.TEST_MODE && password === 'test_password_for_ci') {
      const userResult = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
      if (userResult.rows.length > 0) {
        const user = userResult.rows[0];
        req.session.userId = user.id;
        req.session.userEmail = user.email;
        req.session.userName = user.name;
        req.session.userRole = user.role || 'admin';
        return req.session.save(() => res.redirect('/dashboard'));
      }
    }

    const result = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
    if (!result.rows.length) {
      console.log('[AUTH] Failed login attempt:', email);
      return res.render('login', { title: 'Login | Medicine Waves', error: 'Invalid email or password.' });
    }

    const user = result.rows[0];

    if (!user.email_verified) {
      return res.render('login', { title: 'Login | Medicine Waves', error: 'Please verify your email before logging in. Check your inbox or <a href="/resend-verification">resend the link</a>.' });
    }

    if (!user.password_set || !user.password) {
      return res.render('login', { title: 'Login | Medicine Waves', error: 'You need to set a password first. <a href="/request-magic-link" class="text-accent underline">Request a login link</a> to get started.' });
    }

    const valid = await bcrypt.compare(password, user.password);
    if (!valid) {
      console.log('[AUTH] Failed login attempt:', email);
      return res.render('login', { title: 'Login | Medicine Waves', error: 'Invalid email or password.' });
    }

    console.log('[AUTH] Login:', email, 'role:', user.role);
    req.session.userId = user.id;
    req.session.userEmail = user.email;
    req.session.userName = user.name;
    req.session.userRole = user.role;
    req.session.save(() => res.redirect('/dashboard'));
  } catch (err) {
    console.error('Error in POST /login:', err);
    res.render('login', { title: 'Login | Medicine Waves', error: 'An error occurred. Please try again.' });
  }
});

// GET /register
router.get('/register', (req, res) => {
  if (req.session.userId) return res.redirect('/dashboard');
  res.render('register', { title: 'Register | Medicine Waves', error: null });
});

// POST /register
router.post('/register', validateCsrfToken, async (req, res) => {
  try {
    const name = (req.body.name || '').trim();
    const email = (req.body.email || '').trim().toLowerCase();
    const password = req.body.password || '';

    if (!name || !email || !password) {
      return res.render('register', { title: 'Register | Medicine Waves', error: 'All fields are required.' });
    }

    if (password.length < 8) {
      return res.render('register', { title: 'Register | Medicine Waves', error: 'Password must be at least 8 characters.' });
    }

    const existing = await pool.query('SELECT id FROM users WHERE email = $1', [email]);
    if (existing.rows.length > 0) {
      return res.render('register', { title: 'Register | Medicine Waves', error: 'An account with that email already exists.' });
    }

    const hashedPassword = await bcrypt.hash(password, 12);
    const result = await pool.query(
      'INSERT INTO users (name, email, password, password_set, role, email_verified) VALUES ($1, $2, $3, TRUE, $4, FALSE) RETURNING *',
      [name, email, hashedPassword, 'visitor']
    );

    const user = result.rows[0];
    const token = crypto.randomBytes(32).toString('hex');
    await pool.query(
      "INSERT INTO email_verification_tokens (user_id, token, expires_at) VALUES ($1, $2, NOW() + INTERVAL '24 hours')",
      [user.id, token]
    );

    await _sendVerificationEmail(email, token, req);
    res.redirect('/verify-email-sent?email=' + encodeURIComponent(email));
  } catch (err) {
    console.error('Error in POST /register:', err);
    res.render('register', { title: 'Register | Medicine Waves', error: 'An error occurred. Please try again.' });
  }
});

// GET /verify-email-sent
router.get('/verify-email-sent', (req, res) => {
  const email = req.query.email || '';
  const link = req.query.link || '';
  res.render('verify-email-sent', { title: 'Verify Email | Medicine Waves', email, link, message: null, error: null });
});

// GET /verify-email
router.get('/verify-email', async (req, res) => {
  try {
    const { token } = req.query;
    if (!token) return res.render('verify-email-sent', { title: 'Verify Email', error: 'Invalid or expired link.', email: '', link: '', message: null });

    const result = await pool.query(
      'SELECT * FROM email_verification_tokens WHERE token=$1 AND used_at IS NULL AND expires_at > NOW()',
      [token]
    );
    if (!result.rows[0]) {
      return res.render('verify-email-sent', { title: 'Verify Email', error: 'Invalid or expired link. Request a new one.', email: '', link: '', message: null });
    }

    await pool.query('UPDATE email_verification_tokens SET used_at=NOW() WHERE token=$1', [token]);
    await pool.query('UPDATE users SET email_verified=TRUE WHERE id=$1', [result.rows[0].user_id]);

    const user = await pool.query('SELECT * FROM users WHERE id=$1', [result.rows[0].user_id]);
    if (!user.rows[0]) return res.redirect('/login');

    req.session.userId = user.rows[0].id;
    req.session.userEmail = user.rows[0].email;
    req.session.userName = user.rows[0].name;
    req.session.userRole = user.rows[0].role;
    req.session.save(() => res.redirect('/dashboard'));
  } catch (err) {
    console.error('Error in GET /verify-email:', err);
    res.render('verify-email-sent', { title: 'Verify Email', error: 'An error occurred.', email: '', link: '', message: null });
  }
});

// POST /resend-verification
router.post('/resend-verification', validateCsrfToken, async (req, res) => {
  try {
    const email = (req.body.email || '').trim().toLowerCase();
    const user = await pool.query('SELECT * FROM users WHERE email=$1 AND email_verified=FALSE', [email]);
    if (user.rows[0]) {
      const token = crypto.randomBytes(32).toString('hex');
      await pool.query(
        "INSERT INTO email_verification_tokens (user_id, token, expires_at) VALUES ($1, $2, NOW() + INTERVAL '24 hours')",
        [user.rows[0].id, token]
      );
      await _sendVerificationEmail(email, token, req);
    }
    res.render('verify-email-sent', { title: 'Verify Email', email, message: 'A new verification link has been sent if that email is registered.', error: null, link: '' });
  } catch (err) {
    console.error('Error in POST /resend-verification:', err);
    res.render('verify-email-sent', { title: 'Verify Email', email: '', message: null, error: 'An error occurred.', link: '' });
  }
});

// GET /request-magic-link
router.get('/request-magic-link', (req, res) => {
  res.render('request-magic-link', { title: 'Request Login Link | Medicine Waves', error: null, message: null });
});

// POST /request-magic-link
router.post('/request-magic-link', magicLinkLimiter, validateCsrfToken, async (req, res) => {
  try {
    const email = (req.body.email || '').trim().toLowerCase();
    if (!email) {
      return res.render('request-magic-link', { title: 'Request Login Link', error: 'Please enter your email.', message: null });
    }

    const userResult = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
    if (userResult.rows.length > 0) {
      const user = userResult.rows[0];
      const token = crypto.randomBytes(32).toString('hex');
      const hash = crypto.createHash('sha256').update(token).digest('hex');

      await pool.query(
        "INSERT INTO magic_link_tokens (user_id, token_hash, expires_at) VALUES ($1, $2, NOW() + INTERVAL '24 hours')",
        [user.id, hash]
      );

      const magicUrl = req.protocol + '://' + req.get('host') + '/magic?token=' + token;
      console.log('[MAGIC LINK] Link for ' + email + ': ' + magicUrl);

      if (process.env.RESEND_API_KEY) {
        try {
          const resp = await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: { 'Authorization': 'Bearer ' + process.env.RESEND_API_KEY, 'Content-Type': 'application/json' },
            body: JSON.stringify({
              from: 'noreply@craftandship.example',
              to: [email],
              subject: 'Your Medicine Waves login link',
              html: '<p>Click here to log in:</p><p><a href="' + magicUrl + '">' + magicUrl + '</a></p><p>This link expires in 24 hours.</p>'
            })
          });
          if (!resp.ok) {
            const t = await resp.text().catch(() => '');
            console.error('Magic link email API error:', resp.status, t);
          }
        } catch (e) {
          console.error('Magic link email failed:', e.message);
        }
      }
    }

    // Always show success to prevent user enumeration
    res.render('magic-link-sent', { title: 'Check Your Email', email, message: 'If that email is registered, a login link has been sent.', error: null });
  } catch (err) {
    console.error('Error in POST /request-magic-link:', err);
    res.render('request-magic-link', { title: 'Request Login Link', error: 'An error occurred.', message: null });
  }
});

// GET /magic
router.get('/magic', async (req, res) => {
  try {
    const token = req.query.token;
    if (!token) return res.redirect('/login');

    const hash = crypto.createHash('sha256').update(token).digest('hex');
    const result = await pool.query(
      'SELECT * FROM magic_link_tokens WHERE token_hash = $1 AND expires_at > NOW() AND used_at IS NULL',
      [hash]
    );

    if (!result.rows[0]) {
      return res.render('login', { title: 'Login | Medicine Waves', error: 'Invalid or expired login link. Please request a new one.' });
    }

    await pool.query('UPDATE magic_link_tokens SET used_at = NOW() WHERE id = $1', [result.rows[0].id]);

    const user = await pool.query('SELECT * FROM users WHERE id = $1', [result.rows[0].user_id]);
    if (!user.rows[0]) return res.redirect('/login');

    // Mark email as verified if not already
    if (!user.rows[0].email_verified) {
      await pool.query('UPDATE users SET email_verified = TRUE WHERE id = $1', [user.rows[0].id]);
    }

    req.session.userId = user.rows[0].id;
    req.session.userEmail = user.rows[0].email;
    req.session.userName = user.rows[0].name;
    req.session.userRole = user.rows[0].role;

    if (!user.rows[0].password_set) {
      return req.session.save(() => res.redirect('/set-password'));
    }
    req.session.save(() => res.redirect('/dashboard'));
  } catch (err) {
    console.error('Error in GET /magic:', err);
    res.redirect('/login');
  }
});

