router.post('/set-password', requireAuth, setPasswordLimiter, validateCsrfToken, async (req, res) => {
  try {
    const password = req.body.password || '';
    const confirmPassword = req.body.confirm_password || '';

    if (!password || password.length < 8) {
      return res.render('set-password', { title: 'Set Password', error: 'Password must be at least 8 characters.' });
    }

    if (password !== confirmPassword) {
      return res.render('set-password', { title: 'Set Password', error: 'Passwords do not match.' });
    }

    const hashed = await bcrypt.hash(password, 12);
    await pool.query('UPDATE users SET password = $1, password_set = TRUE WHERE id = $2', [hashed, req.session.userId]);

    res.redirect('/dashboard');
  } catch (err) {
    console.error('Error in POST /set-password:', err);
    res.render('set-password', { title: 'Set Password', error: 'An error occurred.' });
  }
});

// GET /dashboard
router.get('/dashboard', requireAuth, async (req, res) => {
  try {
    if (req.session.userRole === 'admin') {
      return res.redirect('/admin');
    }
    res.render('dashboard', { title: 'Dashboard | Medicine Waves' });
  } catch (err) {
    console.error('Error in GET /dashboard:', err);
    res.status(500).render('500', { title: 'Error' });
  }
});

// POST /logout
router.post('/logout', validateCsrfToken, (req, res) => {
  req.session.destroy(() => res.redirect('/login'));
});

