      })
    });
    if (!resp.ok) {
      const t = await resp.text().catch(() => '');
      console.error('Verification email API error:', resp.status, t);
    }
  } catch (e) {
    console.error('Email send failed (non-fatal):', e.message);
  }
}

module.exports = router;

