require('dotenv').config();
const express = require('express');
const path = require('path');
const crypto = require('crypto');
const session = require('express-session');
const pgSession = require('connect-pg-simple')(session);
const helmet = require('helmet');
const morgan = require('morgan');
const expressLayouts = require('express-ejs-layouts');
const pool = require('./db');
const { migrate } = require('./db/migrate');
const { requirePasswordSet } = require('./middleware/auth');
const fs = require('fs');

if (process.env.TEST_MODE && process.env.NODE_ENV === 'production') {
  console.error('TEST_MODE must not be set in production');
  process.exit(1);
}

if (!process.env.SESSION_SECRET) {
  console.error('SESSION_SECRET not set');
  process.exit(1);
}

const app = express();
// TIMEZONE_DISPLAY_HELPER (v14): single source of truth for event
// date/time display. Uses explicit timeZone to avoid Node-default-TZ
// drift; reads site_settings.site_timezone if set, else America/Chicago.
app.locals.formatEventTime = function(value, tz) {
  if (!value) return '';
  var d = value instanceof Date ? value : new Date(value);
  if (isNaN(d.getTime())) return '';
  var zone = tz || (global._settingsCache && global._settingsCache.site_timezone) || 'America/Chicago';
  try {
    return d.toLocaleString('en-US', {
      year: 'numeric', month: 'short', day: 'numeric',
      hour: 'numeric', minute: '2-digit', timeZone: zone, timeZoneName: 'short'
    });
  } catch (e) {
    return d.toISOString();
  }
};
app.locals.formatEventDate = function(value, tz) {
  if (!value) return '';
  var d = value instanceof Date ? value : new Date(value);
  if (isNaN(d.getTime())) return '';
  var zone = tz || (global._settingsCache && global._settingsCache.site_timezone) || 'America/Chicago';
  try {
    return d.toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: zone
    });
  } catch (e) {
    return d.toISOString().slice(0, 10);
  }
};

const PORT = process.env.PORT || 3000;

app.set('trust proxy', 1);

app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));
app.use(expressLayouts);
app.set('layout', 'layout');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "https://cdn.jsdelivr.net"],
      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
      fontSrc: ["'self'", "https://fonts.gstatic.com"],
      imgSrc: ["'self'", "data:", "https:"],
      frameSrc: ["'self'", "https://www.youtube.com", "https://www.youtube-nocookie.com", "https://tickets.example"],
      connectSrc: ["'self'", "https://cdn.jsdelivr.net", "https://fonts.googleapis.com", "https://fonts.gstatic.com"]
    }
  }
}));

app.use(express.urlencoded({ extended: false, limit: '1mb' }));

require('./icon_helper')(app);
app.use(express.json({ limit: '1mb' }));
app.use(require('compression')());
app.use(express.static(path.join(__dirname, 'public'), { maxAge: '7d' }));
// Proxy YouTube video thumbnails (ad-blocker safe)
app.get('/api/video-thumb/:videoId', (req, res) => {
  const videoId = req.params.videoId;
  if (!/^[a-zA-Z0-9_-]{11}$/.test(videoId)) return res.status(400).send('Invalid');
  const https = require('https');
  https.get(`https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`, (upstream) => {
    if (upstream.statusCode !== 200) {
      res.type('image/svg+xml').send('<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360" viewBox="0 0 480 360"><rect fill="#1a1a2e" width="480" height="360"/><polygon points="220,140 220,220 280,180" fill="#fff" opacity="0.6"/></svg>');
      return;
    }
    res.set('Content-Type', upstream.headers['content-type'] || 'image/jpeg');
    res.set('Cache-Control', 'public, max-age=86400');
    upstream.pipe(res);
  }).on('error', () => {
    res.type('image/svg+xml').send('<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360" viewBox="0 0 480 360"><rect fill="#1a1a2e" width="480" height="360"/><polygon points="220,140 220,220 280,180" fill="#fff" opacity="0.6"/></svg>');
  });
});

// Serve SVG placeholder for missing gallery/stock images
app.get('/images/:type(gallery|stock)/*', (req, res) => {
  const label = req.params.type === 'gallery' ? 'Photo' : 'Image';
  res.type('image/svg+xml').send(
    '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300" viewBox="0 0 400 300">' +
    '<rect fill="#E8F0F4" width="400" height="300"/>' +
    '<text fill="#9CA3AF" font-family="sans-serif" font-size="14" text-anchor="middle" x="200" y="140">' + label + '</text>' +
    '<path d="M185 160 l15-15 l15 15 M190 175 l5-5 l5 5 l5-5 l5 5" fill="none" stroke="#9CA3AF" stroke-width="1.5"/>' +
    '</svg>'
  );
});


// Ensure uploads directory exists
const uploadsDir = path.join(__dirname, 'public', 'uploads');
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir, { recursive: true });
}

app.use(session({
  store: new pgSession({ pool, tableName: 'user_sessions', createTableIfMissing: true }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 8 * 60 * 60 * 1000
  }
}));

// CSRF middleware
function generateCsrfToken(req, res, next) {
  if (!req.session.csrfToken) {
    req.session.csrfToken = crypto.randomBytes(32).toString('hex');
  }
  res.locals.csrfToken = req.session.csrfToken;
  next();
}

function validateCsrfToken(req, res, next) {
  const token = req.body._csrf || req.headers['x-csrf-token'];
  if (!token || token !== req.session.csrfToken) {
    return res.status(403).send('Invalid or missing CSRF token. Please go back and try again.');
  }
  next();
}

app.use(generateCsrfToken);

// Make session data available to all views
app.use((req, res, next) => {
  res.locals.currentUser = req.session.userId ? {
    id: req.session.userId,
    name: req.session.userName,
    email: req.session.userEmail,
    role: req.session.userRole
  } : null;
  res.locals.isAdmin = req.session.userRole === 'admin';
  res.locals.success = req.query.success || null;
  res.locals.error = req.query.error || null;
  next();
});

app.use(requirePasswordSet);
app.use(morgan('combined'));

// Load site settings into res.locals for all views
app.use(async (req, res, next) => {
  try {
    const result = await pool.query('SELECT key, value FROM site_settings');
    const settings = {};
    result.rows.forEach(row => { settings[row.key] = row.value; });
    res.locals.siteSettings = settings;
    res.locals.settings = res.locals.siteSettings;
  } catch (err) {
    res.locals.siteSettings = {};
  }
  next();
});

// Routes
app.use('/', require('./routes/auth'));
app.use('/', require('./routes/home'));
app.use('/events', require('./routes/events'));
app.use('/gallery', require('./routes/gallery'));
app.use('/photos', require('./routes/photos'));
app.use('/videos', require('./routes/videos'));
app.use('/about', require('./routes/about'));
app.use('/contact', require('./routes/contact'));
app.use('/contact-messages', require('./routes/contact-messages'));
app.use('/admin', require('./routes/admin-dashboard'));
app.use(require('./routes/admin'));
app.use(require('./routes/settings'));
app.use(require('./routes/upload'));

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date() });
});

// Robots.txt
app.get('/robots.txt', (req, res) => {
  res.type('text/plain');
  res.send('User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /api/');
});

// 404 handler
app.use((req, res) => {
  res.status(404).render('404', { title: 'Page Not Found' });
});

// Error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).render('500', { title: 'Error', error: 'Something went wrong.' });
});

// Export for testing
module.exports = app;

// Start server
migrate()
  .then(() => {
    app.listen(PORT, () => console.log('Server running on port', PORT));
  })
  .catch(err => {
    console.error('Database migration failed (will retry on next request):', err.message);
    app.listen(PORT, () => console.log('Server running on port', PORT, '(DB unavailable)'));
  });
